service.method:

		INSERT 
		  INTO SSETL
	         ( HOUSE_CODE
		     , COMPANY_CODE
		     , SMR_NUMBER
		     , SMR_STATUS
		     , ADD_DATE
		     , ADD_TIME
		     , ADD_USER_ID
		     , CHANGE_DATE
		     , CHANGE_TIME
		     , CHANGE_USER_ID
		     , DEL_FLAG
		     , SIGN_STATUS
		     , APPLY_TYPE
		     , SUBJECT
		     , SEAL_USE_TYPE
		     , SUBMISSION_PLACE
		     , ATTACH_NO
		     , REMARK
             , SUBMIT_TYPE
             , SUBMIT_REMARK		     
             , EXT_USE_DETAIL
             , EXT_OUT_EXPECT_DATE
             , EXT_OUT_EXPECT_TIME
             , EXT_IN_EXPECT_DATE
             , EXT_IN_EXPECT_TIME
             , EXT_USE_PLACE
             , EXT_USE_USER_ID 
             , EXT_CPNO_USER_ID
             , EXT_OUT_DATE
             , EXT_OUT_TIME
             , EXT_IN_DATE
             , EXT_IN_TIME
             , EMERGENCY_FLAG
             , EMERGENCY_REMARK
             , ROOT_PATH_TYPE
             , REJECT_REMARK 			 
             , APVID
             , ROW_NUM
			 , ADD_USER_DEPT
	         )
	   VALUES( 
	           ${session.HOUSE_CODE}
	         , ${session.COMPANY_CODE}
	         , ${SMR_NUMBER}
	         , 'N'
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , 'N'
	         , 'T'
	         , ${APPLY_TYPE}
			 , ${SUBJECT}       
	         , ${SEAL_USE_TYPE}
			 , ${SUBMISSION_PLACE}
			 , ${ATTACH_NO}
			 , ${REMARK}
             , ${SUBMIT_TYPE}
             , ${SUBMIT_REMARK}			 
             , ${EXT_USE_DETAIL}			 
             , ${EXT_OUT_EXPECT_DATE}			 
             , SUBSTR( CONCAT(IFNULL(${EXT_OUT_EXPECT_HOUR}, ''), IFNULL(${EXT_OUT_EXPECT_MINUTE}, ''), '000000') ,1,6)			 
             , ${EXT_IN_EXPECT_DATE}
             , SUBSTR(CONCAT(IFNULL(${EXT_IN_EXPECT_HOUR}, ''), IFNULL(${EXT_IN_EXPECT_MINUTE}, ''), '000000') ,1,6)
             , ${EXT_USE_PLACE}			 
             , ${EXT_USE_USER_ID} 			 
             , ${EXT_CPNO_USER_ID}
             , ${EXT_OUT_DATE}
             , ${EXT_OUT_TIME}
             , ${EXT_IN_DATE}
             , ${EXT_IN_TIME}
             , ${EMERGENCY_FLAG}
             , ${EMERGENCY_REMARK}
             , ${ROOT_PATH_TYPE}
             , ${REJECT_REMARK} 			 
             , ${APVID}
			,	(
					SELECT
						CAST(IFNULL(MAX(CAST(ROW_NUM AS SIGNED)),0) + 1 AS CHAR)
					FROM SSETL
					WHERE
						HOUSE_CODE = ${session.HOUSE_CODE}
						AND COMPANY_CODE = ${session.COMPANY_CODE}
						AND APPLY_TYPE = 'CEXT'
				)  
			, ${session.DEPARTMENT}
	       )


UPDATE SSETL SET
	DEL_FLAG = 'Y'
	, CHANGE_DATE      = ${current.DATE}
	, CHANGE_TIME      = ${current.TIME}
	, CHANGE_USER_ID   = ${session.ID}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


UPDATE SSETL SET
	  SMR_STATUS       = ${SMR_STATUS}
	, CONFIRM_DATE     = ${current.DATE}
	, CONFIRM_TIME     = ${current.TIME}
	, CONFIRM_USER_ID  = ${session.ID}
	, EXT_IN_DATE      = ${current.DATE}
	, EXT_IN_TIME      = ${current.TIME}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


UPDATE SSETL SET
	  SMR_STATUS       = ${SMR_STATUS}
	, EXT_OUT_DATE     = ${current.DATE}
	, EXT_OUT_TIME     = ${current.TIME}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


UPDATE SSETL SET
	  CHANGE_DATE      = ${current.DATE}
	, CHANGE_TIME      = ${current.TIME}
	, CHANGE_USER_ID   = ${session.ID}
	, SMR_STATUS       = IFNULL(${SMR_STATUS}, SMR_STATUS)
	, SIGN_DATE        = ${current.DATE}
	, SIGN_TIME        = ${current.TIME}
	, SIGN_USER_ID     = ${session.ID}
	, REJECT_REMARK    = IFNULL(${REJECT_REMARK}, REJECT_REMARK)
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


SELECT SMR_STATUS
	 , (SELECT COUNT(*) FROM SAPPR 
	    WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	      AND COMPANY_CODE = ${session.COMPANY_CODE}
	      AND APP_NO = SETL.SMR_NUMBER
	      AND APP_STATUS = 'C') AS APP_STAGE
FROM SSETL SETL
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}
AND APPLY_TYPE      = 'CEXT'


DELETE FROM SAPPR
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND APP_NO			= ${SMR_NUMBER}


INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${session.COMPANY_CODE}     
      ,${SMR_NUMBER}        
      ,'1'      
      ,(SELECT COUNT(*) + 1
          FROM SPMGT InPMGT
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${SMR_NUMBER}
           AND InPMGT.CONT_GL_SEQ  = '1'
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${session.ID}
      ,${ACTION}           
      ,${IP}
     )


INSERT INTO SSEDC (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMR_SEQ
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, SEAL_TYPE
	, SUBJECT
	, COUNT
	, ATTACH_NO
	, MANAGE_NUMBER
	, SMD_NUMBER
	, SEAL_MG_USER_ID
	, SEAL_MG_DEPT
	, SEAL_MG_SUBJECT
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMR_SEQ             }
	, ${ADD_DATE	        }
	, ${current.TIME        }
	, ${ADD_USER_ID         }
	, 'N'
	, ${SEAL_TYPE           }
	, ${SUBJECT             }
	, ${COUNT               }
	, ${ATTACH_NO           }
	, ${MANAGE_NUMBER       }
	, ${SMD_NUMBER          }
	, ${SEAL_MG_USER_ID     }
	, ${SEAL_MG_DEPT        }
	, ${SEAL_MG_SUBJECT     }
)


DELETE FROM SSEDC
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE}
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 		= ${SMR_NUMBER}


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND CONT_NO      = ${SMR_NUMBER}
   AND CONT_GL_SEQ  = '1'
